(* Tests of type checking against the rules on numbers (numbers.integer-literals and numbers.numeric-types): the range of
   a literal, and the types each operator applies to. Each test prints a
   program's errors as conformance.diagnostic-lines compares them, leaving out warnings. *)

open Diagnostics.Errors

(* numbers.no-implicit-conversions, numbers.wrapping, numbers.bitwise-operators and numbers.unsigned-negation, and expressions.no-string-plus *)
let%expect_test "operators apply only to their types" =
  main "fn f(a: bool) -> bool {\na + a\n}";
  [%expect {| main.lt:2: E0317 |}];
  main "fn f(a: str, b: str) -> str {\na + b\n}";
  [%expect {| main.lt:2: E0317 |}];
  main "fn f(a: bool, b: bool) -> bool {\na & b\n}";
  [%expect {| main.lt:2: E0317 |}];
  main "fn f(a: f64) -> f64 {\na +% a\n}";
  [%expect {| main.lt:2: E0317 |}];
  main "fn f(x: u8) -> u8 {\n-x\n}";
  [%expect {| main.lt:2: E0317 |}];
  main "fn f(a: i64, b: f64) -> f64 {\na * b\n}";
  [%expect {| main.lt:2: E0311 |}];
  main "fn f(a: bool, b: u8, c: i8) -> (bool, u8, i8) {\n(!a, !b & 1, -c)\n}";
  [%expect {| ok |}]

(* numbers.integer-literals, numbers.float-literals and numbers.negative-literals *)
let%expect_test "a literal fits its type" =
  main "fn f() -> u8 {\n256\n}";
  [%expect {| main.lt:2: E0320 |}];
  main "fn f() -> (i8, i8) {\n(-128, -129)\n}";
  [%expect {| main.lt:2: E0320 |}];
  main "fn f() -> u8 {\n-1\n}";
  [%expect {| main.lt:2: E0320 |}];
  main "fn f() -> (f64, f64) {\n(9007199254740992, 9007199254740993)\n}";
  [%expect {| main.lt:2: E0320 |}];
  main "fn f() -> f32 {\n1e39\n}";
  [%expect {| main.lt:2: E0320 |}];
  main "fn f() -> i64 {\n1.5\n}";
  [%expect {| main.lt:2: E0311 |}];
  main "fn f() -> f64 {\nlet x = 1\nx\n}";
  [%expect {| ok |}]

(* numbers.negative-literals *)
let%expect_test "only a - written directly before a literal is part of it" =
  main "fn f() -> i8 {\n-128\n}";
  [%expect {| ok |}];
  main "fn f() -> i8 {\n-(128)\n}";
  [%expect {| main.lt:2: E0320 |}];
  main "fn f() -> i8 {\n- 128\n}";
  [%expect {| main.lt:2: E0320 |}]

(* numbers.float-literals *)
let%expect_test "a float literal's value, not its exponent, decides its range" =
  main
    "fn f() -> f64 {\n\
     .0e-5500\n\
     }";
  [%expect {| main.lt:2: E0320 |}];
  main
    "fn f() -> f64 {\n\
     .0e-5990\n\
     }";
  [%expect {| ok |}]

(* numbers.negative-literals and numbers.unsigned-negation *)
let%expect_test "an unsigned value is negated only as part of a literal" =
  main "fn f() -> (u8, u8, u8) {\n(-0, - 0, -(0))\n}";
  [%expect {|
    main.lt:2: E0317
    main.lt:2: E0317
    |}];
  main "fn f(n: i8) -> i64 {\nmatch n {\n- 128 => 1\n_ => 0\n}\n}";
  [%expect {| ok |}]
